package catalog

import (
	"regexp"
	"slices"
	"sort"
	"strings"
)

// MITRE D3FEND (data/d3fend.yaml, generated by cmd/d3fendgen) and MITRE
// EMB3D (data/emb3d.yaml, generated by cmd/emb3dgen). Requirements and
// tests list the D3FEND defensive techniques they implement or verify
// (d3fend:) and the EMB3D mitigations and threats they address (emb3d:);
// risks list the EMB3D threats that realise them. Every id is checked
// against the lists. Through the D3FEND relations to ATT&CK, the
// catalogue shows for a risk which requirements' defensive techniques
// counter its ATT&CK techniques.

// D3fendTactic is a D3FEND tactic (Model, Harden, Detect, Isolate,
// Deceive, Evict, Restore).
type D3fendTactic struct {
	ID   string `yaml:"id" json:"id"`
	Name string `yaml:"name" json:"name"`
	URL  string `yaml:"url" json:"url"`
}

// D3fendTechnique is a defensive technique (D3-MFA) with its tactic, its
// parent technique and the ATT&CK techniques it counters.
type D3fendTechnique struct {
	ID     string   `yaml:"id" json:"id"`
	Name   string   `yaml:"name" json:"name"`
	Tactic string   `yaml:"tactic" json:"tactic"`
	Parent string   `yaml:"parent" json:"parent,omitempty"`
	URL    string   `yaml:"url" json:"url"`
	Attack []string `yaml:"attack" json:"attack,omitempty"`
}

// D3fendList is the D3FEND list with its version.
type D3fendList struct {
	Version    string            `yaml:"version" json:"version"`
	Release    string            `yaml:"release" json:"release"`
	URL        string            `yaml:"url" json:"url"`
	Tactics    []D3fendTactic    `yaml:"tactics" json:"tactics"`
	Techniques []D3fendTechnique `yaml:"techniques" json:"-"`
}

// Emb3dProperty is an EMB3D device property (PID-11).
type Emb3dProperty struct {
	ID       string `yaml:"id" json:"id"`
	Name     string `yaml:"name" json:"name"`
	Category string `yaml:"category" json:"category"`
	Parent   string `yaml:"parent" json:"parent,omitempty"`
}

// Emb3dThreat is an EMB3D threat (TID-101) with the properties that
// expose a device to it and the mitigations that address it.
type Emb3dThreat struct {
	ID          string   `yaml:"id" json:"id"`
	Name        string   `yaml:"name" json:"name"`
	Category    string   `yaml:"category" json:"category"`
	Maturity    string   `yaml:"maturity" json:"maturity"`
	URL         string   `yaml:"url" json:"url"`
	Properties  []string `yaml:"properties" json:"properties"`
	Mitigations []string `yaml:"mitigations" json:"mitigations"`
}

// Emb3dMitigation is an EMB3D mitigation (MID-001) with the threats it
// addresses (derived).
type Emb3dMitigation struct {
	ID       string   `yaml:"id" json:"id"`
	Name     string   `yaml:"name" json:"name"`
	Maturity string   `yaml:"maturity" json:"maturity"`
	URL      string   `yaml:"url" json:"url"`
	Threats  []string `yaml:"-" json:"threats"`
}

// Emb3dList is the EMB3D list with its version.
type Emb3dList struct {
	Version     string            `yaml:"version" json:"version"`
	URL         string            `yaml:"url" json:"url"`
	Properties  []Emb3dProperty   `yaml:"properties" json:"properties"`
	Threats     []Emb3dThreat     `yaml:"threats" json:"-"`
	Mitigations []Emb3dMitigation `yaml:"mitigations" json:"-"`
}

// Emb3dCategories are the EMB3D threat categories in display order.
var Emb3dCategories = []string{"hardware", "system software", "application software", "networking"}

var (
	d3fendIDRe = regexp.MustCompile(`^D3-[A-Z0-9]{1,10}$`)
	tidRe      = regexp.MustCompile(`^TID-\d{3}$`)
	midRe      = regexp.MustCompile(`^MID-\d{3}$`)
	pidRe      = regexp.MustCompile(`^PID-\d{2,6}$`)
	// refs that cite D3FEND or EMB3D: the fields hold the ids
	frameworkRefRe = regexp.MustCompile(`^MITRE (D3FEND|EMB3D)\b`)
)

// MaxFrameworkIDs bounds the D3FEND or EMB3D ids of one item.
const MaxFrameworkIDs = 8

// loadFrameworks checks the D3FEND and EMB3D lists and indexes them.
func (c *Catalog) loadFrameworks(bad func(string, ...any)) {
	c.d3Tactic, c.d3ByID, c.d3ByAttack = map[string]*D3fendTactic{}, map[string]*D3fendTechnique{}, map[string][]string{}
	for i := range c.D3fend.Tactics {
		t := &c.D3fend.Tactics[i]
		if t.ID == "" || c.d3Tactic[t.ID] != nil || t.Name == "" || !validURL(t.URL) {
			bad("d3fend tactic %q: invalid or duplicate id, or no name or url", t.ID)
		}
		c.d3Tactic[t.ID] = t
	}
	for i := range c.D3fend.Techniques {
		t := &c.D3fend.Techniques[i]
		switch {
		case !d3fendIDRe.MatchString(t.ID) || c.d3ByID[t.ID] != nil:
			bad("d3fend technique %q: invalid or duplicate id", t.ID)
		case t.Name == "" || !validURL(t.URL):
			bad("d3fend technique %s: name and url are needed", t.ID)
		case c.d3Tactic[t.Tactic] == nil:
			bad("d3fend technique %s: unknown tactic %q", t.ID, t.Tactic)
		}
		c.d3ByID[t.ID] = t
	}
	for i := range c.D3fend.Techniques {
		t := &c.D3fend.Techniques[i]
		if t.Parent != "" && c.d3ByID[t.Parent] == nil {
			bad("d3fend technique %s: unknown parent %s", t.ID, t.Parent)
		}
		for _, a := range t.Attack {
			if c.techByID[a] == nil {
				bad("d3fend technique %s: ATT&CK technique %s is not in attack.yaml (regenerate d3fend.yaml after attack.yaml)", t.ID, a)
				continue
			}
			c.d3ByAttack[a] = append(c.d3ByAttack[a], t.ID)
		}
	}
	if len(c.D3fend.Techniques) > 0 && (c.D3fend.Version == "" || !validURL(c.D3fend.URL)) {
		bad("d3fend.yaml: version and url are needed")
	}
	c.embThreat, c.embMit, c.embProp = map[string]*Emb3dThreat{}, map[string]*Emb3dMitigation{}, map[string]*Emb3dProperty{}
	for i := range c.Emb3d.Properties {
		p := &c.Emb3d.Properties[i]
		if !pidRe.MatchString(p.ID) || c.embProp[p.ID] != nil || p.Name == "" {
			bad("emb3d property %q: invalid or duplicate id, or no name", p.ID)
		}
		c.embProp[p.ID] = p
	}
	for i := range c.Emb3d.Mitigations {
		m := &c.Emb3d.Mitigations[i]
		if !midRe.MatchString(m.ID) || c.embMit[m.ID] != nil || m.Name == "" || !validURL(m.URL) {
			bad("emb3d mitigation %q: invalid or duplicate id, or no name or url", m.ID)
		}
		c.embMit[m.ID] = m
	}
	for i := range c.Emb3d.Threats {
		t := &c.Emb3d.Threats[i]
		if !tidRe.MatchString(t.ID) || c.embThreat[t.ID] != nil || t.Name == "" || !validURL(t.URL) || !slices.Contains(Emb3dCategories, t.Category) {
			bad("emb3d threat %q: invalid or duplicate id, no name or url, or unknown category %q", t.ID, t.Category)
		}
		c.embThreat[t.ID] = t
		for _, p := range t.Properties {
			if c.embProp[p] == nil {
				bad("emb3d threat %s: unknown property %s", t.ID, p)
			}
		}
		for _, mid := range t.Mitigations {
			m := c.embMit[mid]
			if m == nil {
				bad("emb3d threat %s: unknown mitigation %s", t.ID, mid)
				continue
			}
			m.Threats = append(m.Threats, t.ID)
		}
	}
	for i := range c.Emb3d.Properties {
		if p := c.Emb3d.Properties[i]; p.Parent != "" && c.embProp[p.Parent] == nil {
			bad("emb3d property %s: unknown parent %s", p.ID, p.Parent)
		}
	}
	if len(c.Emb3d.Threats) > 0 && (c.Emb3d.Version == "" || !validURL(c.Emb3d.URL)) {
		bad("emb3d.yaml: version and url are needed")
	}
}

// checkD3fend checks the d3fend list of item id.
func (c *Catalog) checkD3fend(id string, ids []string, bad func(string, ...any)) {
	if len(ids) > MaxFrameworkIDs {
		bad("%s: %d D3FEND techniques, at most %d", id, len(ids), MaxFrameworkIDs)
	}
	seen := map[string]bool{}
	for _, x := range ids {
		switch {
		case seen[x]:
			bad("%s: D3FEND technique %s listed twice", id, x)
		case c.d3ByID[x] == nil:
			bad("%s: unknown D3FEND technique %q (see data/d3fend.yaml)", id, x)
		}
		seen[x] = true
	}
	for _, x := range ids {
		for p := c.d3ByID[x]; p != nil && p.Parent != ""; p = c.d3ByID[p.Parent] {
			if seen[p.Parent] {
				bad("%s: d3fend lists both %s and its sub-technique %s: keep the sub-technique", id, p.Parent, x)
			}
		}
	}
}

// checkEmb3d checks the emb3d list of item id: threats (TID) and, unless
// threatsOnly, mitigations (MID).
func (c *Catalog) checkEmb3d(id string, ids []string, threatsOnly bool, bad func(string, ...any)) {
	if len(ids) > MaxFrameworkIDs {
		bad("%s: %d EMB3D ids, at most %d", id, len(ids), MaxFrameworkIDs)
	}
	seen := map[string]bool{}
	for _, x := range ids {
		switch {
		case seen[x]:
			bad("%s: EMB3D id %s listed twice", id, x)
		case threatsOnly && c.embThreat[x] == nil:
			bad("%s: unknown EMB3D threat %q (a risk lists threats TID-nnn of data/emb3d.yaml)", id, x)
		case !threatsOnly && c.embThreat[x] == nil && c.embMit[x] == nil:
			bad("%s: unknown EMB3D threat or mitigation %q (see data/emb3d.yaml)", id, x)
		}
		seen[x] = true
	}
}

// checkFrameworkRefs rejects refs that cite D3FEND or EMB3D: the ids go
// in the d3fend and emb3d fields.
func checkFrameworkRefs(id string, refs []string, bad func(string, ...any)) {
	for _, r := range refs {
		if m := frameworkRefRe.FindStringSubmatch(r); m != nil {
			bad("%s: ref %q: list %s ids in %s, not in refs", id, r, m[1], strings.ToLower(m[1]))
		}
	}
}

// checkFrameworks checks the D3FEND and EMB3D fields of every item.
func (c *Catalog) checkFrameworks(bad func(string, ...any)) {
	for _, a := range c.Areas {
		for _, r := range a.Requirements {
			c.checkD3fend(r.ID, r.D3fend, bad)
			c.checkEmb3d(r.ID, r.Emb3d, false, bad)
			checkFrameworkRefs(r.ID, r.Refs, bad)
		}
		for _, t := range a.Tests {
			c.checkD3fend(t.ID, t.D3fend, bad)
			c.checkEmb3d(t.ID, t.Emb3d, false, bad)
			checkFrameworkRefs(t.ID, t.Refs, bad)
		}
		for _, k := range a.Risks {
			c.checkEmb3d(k.ID, k.Emb3d, true, bad)
			checkFrameworkRefs(k.ID, k.Refs, bad)
			if len(k.Emb3d) > 0 && slices.Contains(NoAttackCategories, k.Category) {
				bad("%s: a %s risk is not caused by an adversary: it lists no EMB3D threat", k.ID, k.Category)
			}
		}
	}
}

// D3fendTechnique returns the D3FEND technique with id, or nil.
func (c *Catalog) D3fendTechnique(id string) *D3fendTechnique { return c.d3ByID[id] }

// Emb3dThreat returns the EMB3D threat with id, or nil.
func (c *Catalog) Emb3dThreat(id string) *Emb3dThreat { return c.embThreat[id] }

// Emb3dMitigation returns the EMB3D mitigation with id, or nil.
func (c *Catalog) Emb3dMitigation(id string) *Emb3dMitigation { return c.embMit[id] }

// NormalizeFrameworkID returns a D3FEND or EMB3D id in canonical form
// (upper case, trimmed: "d3-mfa" → "D3-MFA", "tid-101" → "TID-101").
func NormalizeFrameworkID(id string) string { return strings.ToUpper(strings.TrimSpace(id)) }

// ValidD3fend reports whether id is a D3FEND technique.
func (c *Catalog) ValidD3fend(id string) bool { return c.d3ByID[id] != nil }

// ValidEmb3d reports whether id is an EMB3D threat or, unless threatsOnly,
// an EMB3D mitigation.
func (c *Catalog) ValidEmb3d(id string, threatsOnly bool) bool {
	return c.embThreat[id] != nil || (!threatsOnly && c.embMit[id] != nil)
}

// D3fendSummary is a D3FEND technique for display.
type D3fendSummary struct {
	ID         string `json:"id"`
	Name       string `json:"name"`
	Tactic     string `json:"tactic"`
	Parent     string `json:"parent,omitempty"`
	ParentName string `json:"parent_name,omitempty"`
	URL        string `json:"url"`
	// Attack counts the ATT&CK techniques it counters.
	Attack int `json:"attack"`
}

// SummarizeD3fend returns the D3FEND technique with id for display (only
// the id when unknown).
func (c *Catalog) SummarizeD3fend(id string) D3fendSummary {
	t := c.d3ByID[id]
	if t == nil {
		return D3fendSummary{ID: id}
	}
	s := D3fendSummary{ID: t.ID, Name: t.Name, Tactic: t.Tactic, Parent: t.Parent, URL: t.URL, Attack: len(t.Attack)}
	if p := c.d3ByID[t.Parent]; p != nil {
		s.ParentName = p.Name
	}
	return s
}

// D3fendSummaries returns the techniques with ids for display.
func (c *Catalog) D3fendSummaries(ids []string) []D3fendSummary {
	out := make([]D3fendSummary, 0, len(ids))
	for _, id := range ids {
		out = append(out, c.SummarizeD3fend(id))
	}
	return out
}

// Emb3dSummary is an EMB3D threat or mitigation for display.
type Emb3dSummary struct {
	ID string `json:"id"`
	// Kind is "threat" or "mitigation" ("" unknown).
	Kind     string `json:"kind"`
	Name     string `json:"name"`
	Category string `json:"category,omitempty"`
	Maturity string `json:"maturity,omitempty"`
	URL      string `json:"url"`
}

// SummarizeEmb3d returns the EMB3D threat or mitigation with id.
func (c *Catalog) SummarizeEmb3d(id string) Emb3dSummary {
	if t := c.embThreat[id]; t != nil {
		return Emb3dSummary{ID: t.ID, Kind: "threat", Name: t.Name, Category: t.Category, Maturity: t.Maturity, URL: t.URL}
	}
	if m := c.embMit[id]; m != nil {
		return Emb3dSummary{ID: m.ID, Kind: "mitigation", Name: m.Name, Maturity: m.Maturity, URL: m.URL}
	}
	return Emb3dSummary{ID: id}
}

// Emb3dSummaries returns the EMB3D items with ids for display.
func (c *Catalog) Emb3dSummaries(ids []string) []Emb3dSummary {
	out := make([]Emb3dSummary, 0, len(ids))
	for _, id := range ids {
		out = append(out, c.SummarizeEmb3d(id))
	}
	return out
}

// D3fendTacticsOf returns the tactics of the D3FEND techniques ids.
func (c *Catalog) D3fendTacticsOf(ids []string) []string {
	var out []string
	for _, id := range ids {
		if t := c.d3ByID[id]; t != nil && !slices.Contains(out, t.Tactic) {
			out = append(out, t.Tactic)
		}
	}
	return out
}

// d3fendMatches reports whether one of ids is in want (lower case ids or
// tactic names) or a sub-technique of one of them.
func (c *Catalog) d3fendMatches(ids []string, want map[string]bool) bool {
	for _, id := range ids {
		for t := c.d3ByID[id]; t != nil; t = c.d3ByID[t.Parent] {
			if want[strings.ToLower(t.ID)] || want[strings.ToLower(t.Tactic)] {
				return true
			}
			if t.Parent == "" {
				break
			}
		}
		if want[strings.ToLower(id)] {
			return true
		}
	}
	return false
}

// emb3dMatches reports whether ids address one of want (lower case): an
// id listed itself, or a mitigation of a wanted threat, or a threat a
// wanted mitigation addresses.
func (c *Catalog) emb3dMatches(ids []string, want map[string]bool) bool {
	for _, id := range ids {
		if want[strings.ToLower(id)] {
			return true
		}
		if m := c.embMit[id]; m != nil {
			for _, t := range m.Threats {
				if want[strings.ToLower(t)] {
					return true
				}
			}
		}
		if t := c.embThreat[id]; t != nil {
			if want[strings.ToLower(t.Category)] {
				return true
			}
		}
	}
	return false
}

// Emb3dThreatsOf returns the threats ids address: the threats listed and
// those of the mitigations listed, distinct and sorted.
func (c *Catalog) Emb3dThreatsOf(ids []string) []string {
	var out []string
	for _, id := range ids {
		if c.embThreat[id] != nil && !slices.Contains(out, id) {
			out = append(out, id)
		}
		if m := c.embMit[id]; m != nil {
			for _, t := range m.Threats {
				if !slices.Contains(out, t) {
					out = append(out, t)
				}
			}
		}
	}
	sort.Strings(out)
	return out
}

// frameworkTerms are the ids and names of an item's D3FEND and EMB3D
// entries, for the free-text search ("D3-MFA", "secure boot").
func (c *Catalog) frameworkTerms(d3 []string, emb []string) []string {
	var out []string
	for _, id := range d3 {
		out = append(out, id)
		if t := c.d3ByID[id]; t != nil {
			out = append(out, t.Name)
		}
	}
	for _, id := range emb {
		out = append(out, id, c.SummarizeEmb3d(id).Name)
	}
	return out
}

// DefenseRequirement is a catalogue requirement whose D3FEND techniques
// counter a risk's ATT&CK technique.
type DefenseRequirement struct {
	ID    string `json:"id"`
	Title string `json:"title"`
	// D3fend are its techniques that counter the ATT&CK technique;
	// Mitigates is set when the risk lists it in mitigated_by.
	D3fend    []string `json:"d3fend"`
	Mitigates bool     `json:"mitigates"`
}

// RiskDefense is an ATT&CK technique of a risk with the D3FEND techniques
// that counter it and the catalogue requirements that implement them.
type RiskDefense struct {
	Technique TechniqueSummary `json:"technique"`
	// D3fend are the D3FEND techniques that counter it (by D3FEND's
	// inference); Requirements the catalogue requirements that list one,
	// the risk's own mitigating requirements first (at most
	// MaxDefenseRequirements others).
	D3fend       []D3fendSummary      `json:"d3fend"`
	Requirements []DefenseRequirement `json:"requirements"`
	// Covered: one of the risk's mitigating requirements counters it; a
	// technique that is not covered is a gap.
	Covered bool `json:"covered"`
}

// MaxDefenseRequirements bounds the other catalogue requirements a risk
// defense suggests.
const MaxDefenseRequirements = 8

// CountersOf returns the D3FEND techniques that counter the ATT&CK
// technique id (or its parent technique).
func (c *Catalog) CountersOf(id string) []string {
	out := append([]string{}, c.d3ByAttack[id]...)
	if t := c.techByID[id]; t != nil && t.Parent != "" {
		for _, x := range c.d3ByAttack[t.Parent] {
			if !slices.Contains(out, x) {
				out = append(out, x)
			}
		}
	}
	sort.Strings(out)
	return out
}

// RiskDefenses returns, for each ATT&CK technique of k, the D3FEND
// techniques that counter it and the catalogue requirements that list
// one: the coverage of the risk by defensive techniques.
func (c *Catalog) RiskDefenses(k *Risk, lang string) []RiskDefense {
	out := []RiskDefense{}
	area := c.Area(k.Area)
	for _, tid := range k.Attack {
		ts, _ := c.SummarizeTechnique(tid)
		counters := c.CountersOf(tid)
		d := RiskDefense{Technique: ts, D3fend: c.D3fendSummaries(counters), Requirements: []DefenseRequirement{}}
		hit := func(r *Requirement) []string {
			var x []string
			for _, id := range r.D3fend {
				if slices.Contains(counters, id) {
					x = append(x, id)
				}
			}
			return x
		}
		for _, rid := range k.MitigatedBy {
			if r := c.Requirements[rid]; r != nil {
				if x := hit(r); len(x) > 0 {
					d.Requirements = append(d.Requirements, DefenseRequirement{ID: r.ID, Title: r.Localized(lang).Title, D3fend: x, Mitigates: true})
					d.Covered = true
				}
			}
		}
		// other requirements, those of the risk's catalogue type first
		var same, other []DefenseRequirement
		for _, a := range c.OrderedAreas() {
			for i := range a.Requirements {
				r := &a.Requirements[i]
				if slices.Contains(k.MitigatedBy, r.ID) {
					continue
				}
				if x := hit(r); len(x) > 0 {
					dr := DefenseRequirement{ID: r.ID, Title: r.Localized(lang).Title, D3fend: x}
					if area != nil && a.Catalogue == area.Catalogue {
						same = append(same, dr)
					} else {
						other = append(other, dr)
					}
				}
			}
		}
		more := append(same, other...)
		if len(more) > MaxDefenseRequirements {
			more = more[:MaxDefenseRequirements]
		}
		d.Requirements = append(d.Requirements, more...)
		out = append(out, d)
	}
	return out
}

// D3fendCoverageTechnique is a D3FEND technique with the catalogue items
// that list it (or one of its sub-techniques).
type D3fendCoverageTechnique struct {
	ID           string `json:"id"`
	Name         string `json:"name"`
	Parent       string `json:"parent,omitempty"`
	URL          string `json:"url"`
	Requirements int    `json:"requirements"`
	Tests        int    `json:"tests"`
}

// D3fendCoverageTactic is a tactic with the techniques used.
type D3fendCoverageTactic struct {
	ID           string `json:"id"`
	Name         string `json:"name"`
	URL          string `json:"url"`
	Requirements int    `json:"requirements"`
	Tests        int    `json:"tests"`
	// Used and Total count the tactic's techniques listed by an item and
	// all of them.
	Used       int                       `json:"used"`
	Total      int                       `json:"total"`
	Techniques []D3fendCoverageTechnique `json:"techniques"`
}

// D3fendCoverage is the coverage of the D3FEND tactics by catalogue
// requirements and tests.
type D3fendCoverage struct {
	Version string                 `json:"version"`
	URL     string                 `json:"url"`
	Tactics []D3fendCoverageTactic `json:"tactics"`
	// Risks counts the catalogue risks with ATT&CK techniques, Covered
	// those of them whose every technique is countered by a mitigating
	// requirement, Gaps the ATT&CK techniques of risks that none counters.
	Risks   int `json:"risks"`
	Covered int `json:"covered"`
	Gaps    int `json:"gaps"`
}

// D3fendCoverage returns, per D3FEND tactic, the techniques the catalogue
// requirements and tests (in the catalogue types of catalogue, "" = all)
// list, with counts; parents count the items of their sub-techniques.
func (c *Catalog) D3fendCoverage(catalogue string) D3fendCoverage {
	kinds := set(catalogue)
	reqs, tests := map[string]map[string]bool{}, map[string]map[string]bool{}
	add := func(m map[string]map[string]bool, tech, item string) {
		for t := c.d3ByID[tech]; t != nil; t = c.d3ByID[t.Parent] {
			if m[t.ID] == nil {
				m[t.ID] = map[string]bool{}
			}
			m[t.ID][item] = true
			if t.Parent == "" {
				break
			}
		}
	}
	out := D3fendCoverage{Version: c.D3fend.Version, URL: c.D3fend.URL, Tactics: []D3fendCoverageTactic{}}
	for _, a := range c.Areas {
		if !accepts(kinds, a.Catalogue) {
			continue
		}
		for _, r := range a.Requirements {
			for _, id := range r.D3fend {
				add(reqs, id, r.ID)
			}
		}
		for _, t := range a.Tests {
			for _, id := range t.D3fend {
				add(tests, id, t.ID)
			}
		}
		for i := range a.Risks {
			k := &a.Risks[i]
			if len(k.Attack) == 0 {
				continue
			}
			out.Risks++
			all := true
			for _, d := range c.riskCoverage(k) {
				if !d {
					all = false
					out.Gaps++
				}
			}
			if all {
				out.Covered++
			}
		}
	}
	for _, ta := range c.D3fend.Tactics {
		ct := D3fendCoverageTactic{ID: ta.ID, Name: ta.Name, URL: ta.URL, Techniques: []D3fendCoverageTechnique{}}
		rs, ts := map[string]bool{}, map[string]bool{}
		for _, t := range c.D3fend.Techniques {
			if t.Tactic != ta.ID {
				continue
			}
			ct.Total++
			if len(reqs[t.ID])+len(tests[t.ID]) == 0 {
				continue
			}
			ct.Used++
			ct.Techniques = append(ct.Techniques, D3fendCoverageTechnique{ID: t.ID, Name: t.Name, Parent: t.Parent, URL: t.URL, Requirements: len(reqs[t.ID]), Tests: len(tests[t.ID])})
			for x := range reqs[t.ID] {
				rs[x] = true
			}
			for x := range tests[t.ID] {
				ts[x] = true
			}
		}
		ct.Requirements, ct.Tests = len(rs), len(ts)
		out.Tactics = append(out.Tactics, ct)
	}
	return out
}

// riskCoverage reports for each ATT&CK technique of k whether one of its
// mitigating requirements lists a D3FEND technique that counters it.
func (c *Catalog) riskCoverage(k *Risk) []bool {
	out := make([]bool, len(k.Attack))
	for i, tid := range k.Attack {
		counters := c.CountersOf(tid)
		for _, rid := range k.MitigatedBy {
			if r := c.Requirements[rid]; r != nil && slices.ContainsFunc(r.D3fend, func(x string) bool { return slices.Contains(counters, x) }) {
				out[i] = true
				break
			}
		}
	}
	return out
}

// Emb3dCoverageThreat is an EMB3D threat with the catalogue items that
// address it: risks that list it, requirements and tests that list it or
// one of its mitigations.
type Emb3dCoverageThreat struct {
	ID           string `json:"id"`
	Name         string `json:"name"`
	URL          string `json:"url"`
	Risks        int    `json:"risks"`
	Requirements int    `json:"requirements"`
	Tests        int    `json:"tests"`
}

// Emb3dCoverageCategory is a threat category with its threats.
type Emb3dCoverageCategory struct {
	ID           string                `json:"id"`
	Risks        int                   `json:"risks"`
	Requirements int                   `json:"requirements"`
	Tests        int                   `json:"tests"`
	Addressed    int                   `json:"addressed"`
	Total        int                   `json:"total"`
	Threats      []Emb3dCoverageThreat `json:"threats"`
}

// Emb3dCoverage is the coverage of the EMB3D threats by the catalogue.
type Emb3dCoverage struct {
	Version    string                  `json:"version"`
	URL        string                  `json:"url"`
	Categories []Emb3dCoverageCategory `json:"categories"`
	// Mitigations counts the EMB3D mitigations listed by an item.
	Mitigations int `json:"mitigations"`
}

// Emb3dCoverage returns, per EMB3D threat category, every threat with the
// catalogue risks, requirements and tests (in the catalogue types of
// catalogue, "" = all) that address it. A threat no requirement addresses
// is a gap.
func (c *Catalog) Emb3dCoverage(catalogue string) Emb3dCoverage {
	kinds := set(catalogue)
	risks, reqs, tests := map[string]map[string]bool{}, map[string]map[string]bool{}, map[string]map[string]bool{}
	mits := map[string]bool{}
	add := func(m map[string]map[string]bool, ids []string, item string) {
		for _, id := range ids {
			if c.embMit[id] != nil {
				mits[id] = true
			}
		}
		for _, t := range c.Emb3dThreatsOf(ids) {
			if m[t] == nil {
				m[t] = map[string]bool{}
			}
			m[t][item] = true
		}
	}
	for _, a := range c.Areas {
		if !accepts(kinds, a.Catalogue) {
			continue
		}
		for _, k := range a.Risks {
			add(risks, k.Emb3d, k.ID)
		}
		for _, r := range a.Requirements {
			add(reqs, r.Emb3d, r.ID)
		}
		for _, t := range a.Tests {
			add(tests, t.Emb3d, t.ID)
		}
	}
	out := Emb3dCoverage{Version: c.Emb3d.Version, URL: c.Emb3d.URL, Categories: []Emb3dCoverageCategory{}, Mitigations: len(mits)}
	for _, cat := range Emb3dCategories {
		cc := Emb3dCoverageCategory{ID: cat, Threats: []Emb3dCoverageThreat{}}
		rk, rq, ts := map[string]bool{}, map[string]bool{}, map[string]bool{}
		for _, t := range c.Emb3d.Threats {
			if t.Category != cat {
				continue
			}
			cc.Total++
			if len(reqs[t.ID]) > 0 {
				cc.Addressed++
			}
			cc.Threats = append(cc.Threats, Emb3dCoverageThreat{ID: t.ID, Name: t.Name, URL: t.URL, Risks: len(risks[t.ID]), Requirements: len(reqs[t.ID]), Tests: len(tests[t.ID])})
			for x := range risks[t.ID] {
				rk[x] = true
			}
			for x := range reqs[t.ID] {
				rq[x] = true
			}
			for x := range tests[t.ID] {
				ts[x] = true
			}
		}
		cc.Risks, cc.Requirements, cc.Tests = len(rk), len(rq), len(ts)
		out.Categories = append(out.Categories, cc)
	}
	return out
}

// riskCounteredBy reports whether one of the D3FEND techniques want (ids
// or tactics, lower case, see d3fendMatches) counters an ATT&CK technique
// of k.
func (c *Catalog) riskCounteredBy(k *Risk, want map[string]bool) bool {
	for _, tid := range k.Attack {
		if c.d3fendMatches(c.CountersOf(tid), want) {
			return true
		}
	}
	return false
}
